const EMPTY_ARRAY = Object.freeze([]);
const EMPTY_OBJECT = Object.freeze({});

function normalizeAccountToolTodoItem(item, workspaceId = "") {
  if (!item || typeof item !== "object") {
    return null;
  }
  const id = String(item.id || item.todo_id || "").trim();
  const text = String(
    item.text || item.todo_text || item.body || item.title || "",
  ).trim();
  if (!id || !text) {
    return null;
  }
  const itemWorkspaceId = String(item.workspace_id || workspaceId || "").trim();
  if (workspaceId && itemWorkspaceId && itemWorkspaceId !== workspaceId) {
    return null;
  }
  const status = accountToolTodoStatus(item);
  return {
    ...item,
    id,
    kind: item.kind || item.type || "todo",
    ...(status && status !== "listed" ? { status, todo_status: status } : {}),
    text,
    workspace_id: itemWorkspaceId || workspaceId,
  };
}


function normalizeAccountToolTodoStatus(value) {
  const status = String(value || "").trim().toLowerCase().replace(/[-\s]+/g, "_");
  if (!status) {
    return "";
  }
  if (["queued", "pending", "requested"].includes(status)) {
    return "queued";
  }
  if (["listed", "list", "in_list", "ready", "released", "unqueued", "unqueue"].includes(status)) {
    return "listed";
  }
  if (["sending", "submitted", "running", "dispatching", "in_flight", "active", "processing"].includes(status)) {
    return "running";
  }
  if (["complete", "completed", "done", "finished", "success"].includes(status)) {
    return "completed";
  }
  if (["cancelled", "canceled"].includes(status)) {
    return "cancelled";
  }
  if (["failed", "failure", "error", "blocked", "rejected"].includes(status)) {
    return "failed";
  }
  if (["interrupted", "aborted"].includes(status)) {
    return "interrupted";
  }
  if (["timed_out", "timeout", "expired"].includes(status)) {
    return "timed_out";
  }
  if (["deleted", "removed"].includes(status)) {
    return "deleted";
  }
  return status;
}

function accountToolTodoStatus(item) {
  const explicitStatus = normalizeAccountToolTodoStatus(
    item?.todo_status || item?.status || "",
  );
  if (explicitStatus) {
    return explicitStatus;
  }
  if (item?.todo_failed_at || item?.failed_at) {
    return "failed";
  }
  if (item?.todo_timed_out_at || item?.timed_out_at || item?.timeout_at) {
    return "timed_out";
  }
  if (item?.todo_interrupted_at || item?.interrupted_at) {
    return "interrupted";
  }
  if (item?.todo_cancelled_at || item?.cancelled_at || item?.canceled_at) {
    return "cancelled";
  }
  if (item?.todo_completed_at || item?.completed_at) {
    return "completed";
  }
  return "";
}



