function documentDraftFingerprint(value) {
  const text = String(value ?? "");
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a32:${(hash >>> 0).toString(16).padStart(8, "0")}:${text.length}`;
}

function documentDraftFallbackFileName(title, extension) {
  const stem = String(title || "untitled")
    .trim()
    .replace(/\.(?:md|markdown|arch)$/iu, "")
    .replace(/[^A-Za-z0-9]+/gu, "_")
    .replace(/^_+|_+$/gu, "")
    .slice(0, 80)
    || "untitled";
  return `${stem}.${String(extension || "md").replace(/^\./u, "") || "md"}`;
}























const MAX_WORKSPACE_TERMINAL_COUNT = 24;
const CLOUD_DESKTOP_DEVICE_PROFILE_RETRY_DELAYS_MS = [500, 1500, 5000, 15000, 30000];

function safeCloudMcpText(value, fallback = "") {
  if (typeof value !== "string") {
    return fallback;
  }
  const trimmed = value.trim();
  return trimmed ? trimmed.slice(0, 500) : fallback;
}

function safeCloudMcpArray(value) {
  return Array.isArray(value) ? value : [];
}

function safeCloudMcpBool(value, fallback = false) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (["1", "true", "yes", "on", "connected", "online", "active", "open", "ready", "live"].includes(normalized)) return true;
    if (["0", "false", "no", "off", "disconnected", "offline", "inactive", "closed", "stale"].includes(normalized)) return false;
  }
  return fallback;
}

function normalizeCloudDeviceText(value) {
  return String(value || "").trim().toLowerCase().replace(/[\s_]+/g, "-");
}

const CLOUD_DEVICE_ALIAS_KEYS = [
  "id",
  "device_id",
  "machine_id",
  "native_device_id",
  "desktop_device_id",
  "target_device_id",
  "target_native_device_id",
  "web_device_id",
  "web_presence_device_id",
  "current_web_device_id",
  "matched_device_id",
  "requested_target_device_id",
  // Server-side fold linking fields: keep a row that migrated identity (new
  // native id, or a durable-web standalone card) merging with its canonical
  // device instead of splitting into a duplicate card.
  "card_id",
  "physical_device_id",
  "bound_native_device_id",
  "device_aliases",
  "replaced_web_device_ids",
];

function cloudDeviceBoolFromKeys(object, keys, fallback = null) {
  if (!object || typeof object !== "object") {
    return fallback;
  }
  for (const key of keys) {
    if (object[key] === undefined || object[key] === null) {
      continue;
    }
    return safeCloudMcpBool(object[key], fallback ?? false);
  }
  return fallback;
}

function cloudDeviceSurfaceRecord(device, surfaceId) {
  const surfaces = device?.surfaces;
  if (Array.isArray(surfaces)) {
    return surfaces.find((surface) => normalizeCloudDeviceText(surface?.id || surface?.label || surface?.name) === surfaceId) || {};
  }
  if (surfaces && typeof surfaces === "object") {
    const direct = surfaces[surfaceId] || surfaces[surfaceId.toLowerCase()];
    return direct && typeof direct === "object" ? direct : {};
  }
  return {};
}

function cloudDeviceAliasList(device, primaryId = "") {
  const aliases = new Set();
  const append = (value) => {
    if (Array.isArray(value)) {
      value.forEach(append);
      return;
    }
    if (value && typeof value === "object") {
      CLOUD_DEVICE_ALIAS_KEYS.forEach((key) => append(value[key]));
      return;
    }
    if (typeof value !== "string" && typeof value !== "number") {
      return;
    }
    const id = safeCloudMcpText(String(value), "").toLowerCase();
    if (id) {
      aliases.add(id);
    }
  };
  append(primaryId);
  append(device);
  append(device?.device);
  append(device?.raw_device);
  append(device?.web_presence);
  append(cloudDeviceSurfaceRecord(device, "native"));
  append(cloudDeviceSurfaceRecord(device, "web"));
  return Array.from(aliases);
}

function uniqueCloudDeviceAliases(...aliasLists) {
  return cloudDeviceAliasList({ device_aliases: aliasLists }, "");
}

function cloudDeviceAliasesIntersect(left = [], right = []) {
  const rightSet = new Set(uniqueCloudDeviceAliases(right));
  return uniqueCloudDeviceAliases(left).some((alias) => rightSet.has(alias));
}

function firstCloudDeviceObject(...values) {
  return values.find((value) => value && typeof value === "object" && !Array.isArray(value)) || {};
}

function collectCloudDeviceIdsFromValue(value, ids = new Set()) {
  if (!value) {
    return ids;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => collectCloudDeviceIdsFromValue(item, ids));
    return ids;
  }
  if (typeof value === "object") {
    cloudDeviceAliasList(value).forEach((id) => ids.add(id));
    return ids;
  }
  const id = safeCloudMcpText(String(value), "").toLowerCase();
  if (id) {
    ids.add(id);
  }
  return ids;
}

function cloudDeviceConnectionSummaryFromSnapshot(root, snapshotRoot = root) {
  return firstCloudDeviceObject(
    snapshotRoot?.client_connection,
    snapshotRoot?.connection_summary,
    root?.client_connection,
    root?.connection_summary,
  );
}

function cloudDeviceConnectionOverlayFromSnapshot(root, snapshotRoot = root) {
  const summary = cloudDeviceConnectionSummaryFromSnapshot(root, snapshotRoot);
  const activeNativeIds = collectCloudDeviceIdsFromValue([
    summary.active_desktop_device_ids,
    summary.active_native_device_ids,
    summary.active_desktop_devices,
    summary.active_native_devices,
  ]);
  const activeWebTargetIds = collectCloudDeviceIdsFromValue([
    summary.active_web_target_device_ids,
  ]);
  safeCloudMcpArray(summary.active_web_devices).forEach((device) => {
    collectCloudDeviceIdsFromValue(
      device?.target_device_id || device?.target_native_device_id,
      activeWebTargetIds,
    );
  });
  return {
    activeNativeIds,
    activeWebTargetIds,
  };
}

function applyCloudDeviceConnectionOverlay(candidates, overlay = {}) {
  const activeNativeIds = overlay.activeNativeIds || new Set();
  const activeWebTargetIds = overlay.activeWebTargetIds || new Set();
  if (!activeNativeIds.size && !activeWebTargetIds.size) {
    return candidates;
  }
  return candidates.map((candidate) => {
    if (!candidate || typeof candidate !== "object") {
      return candidate;
    }
    const aliases = cloudDeviceAliasList(candidate);
    const nativeOverlayActive = aliases.some((id) => activeNativeIds.has(id));
    const webOverlayActive = aliases.some((id) => activeWebTargetIds.has(id));
    if (!nativeOverlayActive && !webOverlayActive) {
      return candidate;
    }
    return {
      ...candidate,
      connected: true,
      native_connected: nativeOverlayActive ? true : candidate.native_connected,
      status: nativeOverlayActive || webOverlayActive ? "connected" : candidate.status,
      web_connected: webOverlayActive ? true : candidate.web_connected,
    };
  });
}

function cloudDeviceObjectHasEntries(value) {
  if (Array.isArray(value)) {
    return value.length > 0;
  }
  return Boolean(value && typeof value === "object" && Object.keys(value).length > 0);
}

function cloudDeviceIdLooksWebOnly(value) {
  const id = safeCloudMcpText(String(value || ""), "").toLowerCase();
  return !id || id === "dashboard-web" || id.startsWith("web-") || id.startsWith("browser-");
}

function cloudDeviceHasNativeAnchor(device = {}) {
  const web = device.web_presence || cloudDeviceSurfaceRecord(device, "web");
  const nativeSurface = cloudDeviceSurfaceRecord(device, "native");
  const nativeIds = [
    device.device_id,
    device.machine_id,
    device.native_device_id,
    device.desktop_device_id,
    device.target_native_device_id,
    web?.native_device_id,
    nativeSurface?.device_id,
    nativeSurface?.machine_id,
  ].map((value) => safeCloudMcpText(String(value || ""), "").toLowerCase()).filter(Boolean);
  const platformAndForm = [
    device.platform,
    device.os,
    device.form_factor,
    device.device_type,
    web?.web_platform,
    web?.web_form_factor,
  ].map(normalizeCloudDeviceText).join(" ");
  const clientKind = [
    device.client_kind,
    device.client_type,
    device.connection_source,
    device.source,
    nativeSurface?.client_kind,
    nativeSurface?.client_type,
    nativeSurface?.source,
  ].map(normalizeCloudDeviceText).join(" ");
  const mobileLike = ["mobile", "phone", "tablet", "android", "ios", "iphone", "ipad"]
    .some((token) => platformAndForm.includes(token));
  const webLike = clientKind.includes("web")
    || clientKind.includes("browser")
    || clientKind.includes("dashboard")
    || clientKind.includes("next-diffforge");
  const nativeFlag = (cloudDeviceBoolFromKeys(
    device,
    ["native_connected", "native_online", "native_active"],
  ) ?? cloudDeviceBoolFromKeys(nativeSurface, ["connected", "active", "online", "open", "status", "state"])) === true;
  const nativeLike = ["native", "desktop", "tauri", "rust"].some((token) => clientKind.includes(token));
  const workspaceCount = Number(device.workspace_count ?? 0) || 0;
  const hasWorkspaces = workspaceCount > 0
    || cloudDeviceObjectHasEntries(device.workspaces)
    || cloudDeviceObjectHasEntries(device.workspace_catalog)
    || cloudDeviceObjectHasEntries(device.workspace_states);
  const hasNativeId = nativeIds.some((id) => !cloudDeviceIdLooksWebOnly(id));
  return Boolean(
    !mobileLike
      && (hasNativeId || hasWorkspaces)
      && (!webLike || nativeFlag || nativeLike || hasWorkspaces)
  );
}

function cloudDevicePlatformLabel(platform) {
  const normalized = normalizeCloudDeviceText(platform);
  if (normalized.includes("mac") || normalized.includes("darwin")) return "macOS";
  if (normalized.includes("win")) return "Windows";
  if (normalized.includes("linux")) return "Linux";
  if (normalized.includes("ios")) return "iOS";
  if (normalized.includes("android")) return "Android";
  return "Unknown OS";
}

function cloudDeviceFormFactorLabel(formFactor, platform) {
  const type = normalizeCloudDeviceText(formFactor);
  const normalizedPlatform = normalizeCloudDeviceText(platform);
  if (
    ["mobile", "phone", "tablet", "ios", "android"].some((item) => (
      type.includes(item) || normalizedPlatform.includes(item)
    ))
  ) {
    return "Mobile";
  }
  if (["web", "browser"].some((item) => type.includes(item))) return "Web";
  if (["pc", "desktop", "laptop", "macbook", "computer"].some((item) => type.includes(item))) return "PC";
  return "Device";
}

function cloudDevicePlatformIcon(device) {
  const explicit = normalizeCloudDeviceText(
    device?.platform_icon || device?.device_icon,
  );
  if (["android", "apple", "ios", "windows", "linux", "mobile", "web", "desktop", "device"].includes(explicit)) {
    return explicit;
  }
  const platform = normalizeCloudDeviceText(device?.platform || device?.os || device?.system);
  const formFactor = normalizeCloudDeviceText(
    device?.form_factor || device?.device_type,
  );
  const source = normalizeCloudDeviceText(
    device?.connection_source || device?.client_kind || device?.source,
  );
  if (platform.includes("android")) return "android";
  if (platform.includes("ios") || platform.includes("iphone") || platform.includes("ipad")) return "ios";
  if (["mobile", "phone", "tablet"].some((item) => formFactor.includes(item))) return "mobile";
  if (platform.includes("mac") || platform.includes("darwin")) return "apple";
  if (platform.includes("win")) return "windows";
  if (platform.includes("linux")) return "linux";
  if (
    ["web", "browser", "next", "dashboard"].some((item) => (
      formFactor.includes(item) || source.includes(item)
    ))
  ) {
    return "web";
  }
  if (["pc", "desktop", "laptop", "macbook", "computer"].some((item) => formFactor.includes(item))) return "desktop";
  return "device";
}

function normalizeCloudConnectedDevice(device, index = 0, options = {}) {
  if (!device || typeof device !== "object") {
    return null;
  }
  const includeOffline = Boolean(options.includeOffline);
  const registered = Boolean(
    options.registered || device.registered || device.registered_device
  );
  const deviceId = safeCloudMcpText(
    device.device_id || device.machine_id || device.id,
    "",
  ).toLowerCase();
  if (!deviceId) {
    // An id-less candidate (its id lived only in a container map key that the
    // Object.values walk discarded). Synthesizing `${name}:${index}` would mint
    // a NEW device key on every event as the index shifts, inserting a fresh
    // duplicate card per snapshot. Drop it — well-formed cloud device rows
    // always carry a device id, and identity must never derive from an index.
    return null;
  }
  const displayName = safeCloudMcpText(
    device.display_name || device.label || device.device_name || device.machine_name || device.hostname || device.name || device.device_model,
    index === 0 ? "Diff Forge client" : `Device ${index + 1}`,
  );
  const statusText = normalizeCloudDeviceText(
    device.status || device.state || device.connection_status,
  );
  const statusConnected = statusText
    ? ["connected", "online", "open", "active", "ready"].includes(statusText)
    : true;
  const genericConnected = safeCloudMcpBool(
    device.connected ?? device.online ?? device.native_connected ?? device.web_connected,
    statusConnected,
  );
  const nativeSurface = cloudDeviceSurfaceRecord(device, "native");
  const webSurface = cloudDeviceSurfaceRecord(device, "web");
  const webPresence = device.web_presence || webSurface;
  const webKindText = [
    device.client_kind,
    device.client_type,
    device.connection_source,
    device.source,
    webPresence?.client_kind,
    webPresence?.source,
    webSurface?.client_kind,
    webSurface?.source,
  ].map(normalizeCloudDeviceText).join(" ");
  const nativeConnectedFromServer = cloudDeviceBoolFromKeys(
    device,
    ["native_connected", "native_online", "native_active"],
  ) ?? cloudDeviceBoolFromKeys(nativeSurface, ["connected", "active", "online", "open", "status", "state"])
    ?? null;
  const webConnectedFromServer = cloudDeviceBoolFromKeys(
    device,
    ["web_connected", "web_active", "web_open", "web_online"],
  ) ?? cloudDeviceBoolFromKeys(webPresence, ["connected", "active", "online", "open", "status", "state"])
    ?? cloudDeviceBoolFromKeys(webSurface, ["connected", "active", "online", "open", "status", "state"])
    ?? (webKindText.includes("web") || webKindText.includes("browser") || webKindText.includes("dashboard") || webKindText.includes("next-diffforge")
      ? cloudDeviceBoolFromKeys(device, ["connected", "online", "live", "active", "status", "state"])
      : null)
    ?? null;
  const hasSurfaceConnectionState = nativeConnectedFromServer !== null || webConnectedFromServer !== null;
  const nativeConnected = nativeConnectedFromServer === true;
  const webConnected = webConnectedFromServer === true;
  const connected = hasSurfaceConnectionState
    ? Boolean(nativeConnected || webConnected)
    : Boolean(genericConnected);
  if (!connected && !includeOffline) {
    return null;
  }
  const platform = safeCloudMcpText(device.platform || device.os || device.system, "");
  const formFactor = safeCloudMcpText(
    device.form_factor || device.device_type,
    "",
  );
  const icon = cloudDevicePlatformIcon(device);
  const deviceAliases = cloudDeviceAliasList(device, deviceId);
  const webOnly = Boolean(
    (webKindText.includes("web") || webKindText.includes("browser") || webKindText.includes("dashboard") || webKindText.includes("next-diffforge"))
      && !cloudDeviceHasNativeAnchor(device)
  );
  return {
    client_kind: device.client_kind || device.client_type || "",
    connected,
    device_aliases: deviceAliases,
    device_id: deviceId,
    display_name: displayName,
    form_factor: formFactor,
    form_factor_label: safeCloudMcpText(
      device.form_factor_label,
      "",
    ) || cloudDeviceFormFactorLabel(formFactor, platform),
    icon,
    native_connected: nativeConnected,
    platform,
    platform_icon: icon,
    platform_label: safeCloudMcpText(
      device.platform_label,
      "",
    ) || cloudDevicePlatformLabel(platform),
    registered,
    source: device.source || device.connection_source || "",
    status: connected ? "connected" : "offline",
    target_device_id: device.target_device_id || device.target_native_device_id || "",
    web_only: webOnly,
    web_connected: webConnected,
    web_presence: webPresence,
  };
}

function cloudDeviceNameIsGeneric(name) {
  const normalized = String(name || "").trim().toLowerCase();
  return (
    !normalized
    || normalized === "this device"
    || normalized === "diff forge client"
    || /^device \d+$/i.test(normalized)
  );
}

function cloudDeviceKeyShouldMigrate(candidateId, currentId, previous = null, next = null) {
  const safeCandidateId = safeCloudMcpText(String(candidateId || ""), "").toLowerCase();
  const safeCurrentId = safeCloudMcpText(String(currentId || ""), "").toLowerCase();
  if (!safeCandidateId || !safeCurrentId || safeCandidateId === safeCurrentId) {
    return false;
  }
  if (cloudDeviceIdLooksWebOnly(safeCurrentId) && !cloudDeviceIdLooksWebOnly(safeCandidateId)) {
    return true;
  }
  return Boolean(previous?.web_only && !next?.web_only && !cloudDeviceIdLooksWebOnly(safeCandidateId));
}

function findCloudDeviceKeyByAliases(devicesById, aliases = []) {
  const aliasList = uniqueCloudDeviceAliases(aliases);
  if (!aliasList.length) {
    return "";
  }
  for (const [deviceId, device] of devicesById.entries()) {
    if (aliasList.includes(deviceId) || cloudDeviceAliasesIntersect(device.device_aliases, aliasList)) {
      return deviceId;
    }
  }
  return "";
}

function mergeCloudConnectedDevice(previous, next) {
  if (!previous) {
    const aliases = uniqueCloudDeviceAliases(next?.device_aliases, next?.device_id);
    return {
      ...next,
      device_aliases: aliases,
      web_only: Boolean(next?.web_only),
    };
  }
  const nextIsWebOverlay = Boolean(next.web_only && previous.web_only !== true);
  const nextIsCanonicalIdentity = Boolean(previous.web_only && !next.web_only);
  const previousNameUseful = !cloudDeviceNameIsGeneric(previous.display_name);
  const nextNameUseful = !cloudDeviceNameIsGeneric(next.display_name);
  const nativeConnected = Boolean(previous.native_connected || next.native_connected);
  const webConnected = Boolean(previous.web_connected || next.web_connected);
  const connected = Boolean(previous.connected || next.connected || nativeConnected || webConnected);
  const aliases = uniqueCloudDeviceAliases(
    previous.device_aliases,
    previous.device_id,
    next.device_aliases,
    next.device_id,
  );
  return {
    ...previous,
    ...next,
    connected,
    device_aliases: aliases,
    client_kind: nextIsWebOverlay ? previous.client_kind || "" : next.client_kind || previous.client_kind || "",
    display_name: !nextIsWebOverlay && nextNameUseful && !previousNameUseful
      ? next.display_name
      : previous.display_name || next.display_name,
    form_factor: nextIsCanonicalIdentity
      ? next.form_factor || previous.form_factor || ""
      : nextIsWebOverlay ? previous.form_factor || "" : previous.form_factor || next.form_factor || "",
    form_factor_label: nextIsCanonicalIdentity
      ? next.form_factor_label || previous.form_factor_label || ""
      : nextIsWebOverlay ? previous.form_factor_label || "" : previous.form_factor_label || next.form_factor_label || "",
    icon: nextIsCanonicalIdentity
      ? next.icon || previous.icon || ""
      : nextIsWebOverlay ? previous.icon || "" : previous.icon || next.icon || "",
    native_connected: nativeConnected,
    platform: nextIsCanonicalIdentity
      ? next.platform || previous.platform || ""
      : nextIsWebOverlay ? previous.platform || "" : previous.platform || next.platform || "",
    platform_icon: nextIsCanonicalIdentity
      ? next.platform_icon || previous.platform_icon || ""
      : nextIsWebOverlay ? previous.platform_icon || "" : previous.platform_icon || next.platform_icon || "",
    platform_label: nextIsCanonicalIdentity
      ? next.platform_label || previous.platform_label || ""
      : nextIsWebOverlay ? previous.platform_label || "" : previous.platform_label || next.platform_label || "",
    source: nextIsWebOverlay ? previous.source || "" : next.source || previous.source || "",
    status: connected ? "connected" : "offline",
    registered: Boolean(previous.registered || next.registered),
    web_connected: webConnected,
    web_only: Boolean(previous.web_only && next.web_only),
  };
}

function upsertCloudConnectedDevice(devicesById, device) {
  if (!device?.device_id) {
    return "";
  }
  const aliases = uniqueCloudDeviceAliases(device.device_aliases, device.device_id);
  const existingKey = findCloudDeviceKeyByAliases(devicesById, aliases);
  const currentKey = existingKey || device.device_id;
  const previous = devicesById.get(currentKey) || null;
  const preferredKey = cloudDeviceKeyShouldMigrate(device.device_id, currentKey, previous, device)
    ? device.device_id
    : currentKey;
  const merged = mergeCloudConnectedDevice(previous, {
    ...device,
    device_aliases: aliases,
    device_id: preferredKey,
  });
  const mergedAliases = uniqueCloudDeviceAliases(merged.device_aliases, aliases, currentKey, preferredKey);
  if (preferredKey !== currentKey) {
    devicesById.delete(currentKey);
  }
  devicesById.set(preferredKey, {
    ...merged,
    device_aliases: mergedAliases,
    device_id: preferredKey,
  });
  return preferredKey;
}

function foldCloudWebOnlyDeviceRows(devicesById) {
  const entries = Array.from(devicesById.entries());
  const canonicalEntries = entries.filter(([, device]) => (
    device
    && device.web_only !== true
    && !cloudDeviceIdLooksWebOnly(device.device_id)
  ));
  if (!canonicalEntries.length) {
    return;
  }
  const hasRegisteredInventory = canonicalEntries.some(([, device]) => device?.registered);
  const canonicalWithWeb = canonicalEntries.filter(([, device]) => device.web_connected === true);
  entries.forEach(([deviceId, device]) => {
    const platformAndForm = [
      device?.platform_icon,
      device?.platform,
      device?.platform_label,
      device?.form_factor,
      device?.form_factor_label,
      device?.icon,
    ].map(normalizeCloudDeviceText).join(" ");
    const mobileLike = ["mobile", "phone", "tablet", "android", "ios", "iphone", "ipad"]
      .some((token) => platformAndForm.includes(token));
    if (!device?.web_only || cloudDeviceRowLooksRegistered(device) || mobileLike) {
      return;
    }
    const targetEntry = canonicalEntries.find(([, candidate]) => (
      cloudDeviceAliasesIntersect(candidate.device_aliases, device.device_aliases)
    )) || (canonicalWithWeb.length === 1
      ? canonicalWithWeb[0]
      : (!hasRegisteredInventory && canonicalEntries.length === 1)
        ? canonicalEntries[0]
        : null);
    if (!targetEntry) {
      if (cloudDeviceNameIsGeneric(device.display_name)) {
        devicesById.delete(deviceId);
      }
      return;
    }
    const [targetDeviceId, targetDevice] = targetEntry;
    const currentTargetDevice = devicesById.get(targetDeviceId) || targetDevice;
    const merged = mergeCloudConnectedDevice(currentTargetDevice, {
      ...device,
      device_id: targetDeviceId,
      client_kind: currentTargetDevice.client_kind,
      display_name: currentTargetDevice.display_name,
      form_factor: currentTargetDevice.form_factor,
      form_factor_label: currentTargetDevice.form_factor_label,
      icon: currentTargetDevice.icon,
      native_connected: currentTargetDevice.native_connected,
      platform: currentTargetDevice.platform,
      platform_icon: currentTargetDevice.platform_icon,
      platform_label: currentTargetDevice.platform_label,
      source: currentTargetDevice.source,
      web_only: false,
    });
    const aliases = uniqueCloudDeviceAliases(merged.device_aliases, currentTargetDevice.device_aliases, device.device_aliases, targetDeviceId, deviceId);
    devicesById.set(targetDeviceId, {
      ...merged,
      device_aliases: aliases,
      device_id: targetDeviceId,
      display_name: currentTargetDevice.display_name || merged.display_name,
      web_only: false,
    });
    devicesById.delete(deviceId);
  });
}

function pruneCloudRowsToRegisteredInventory(devicesById) {
  const registeredEntries = Array.from(devicesById.entries())
    .filter(([, device]) => device?.registered);
  if (!registeredEntries.length) {
    return;
  }
  Array.from(devicesById.entries()).forEach(([deviceId, device]) => {
    if (device?.registered) {
      return;
    }
    const targetEntry = registeredEntries.find(([registeredId, registeredDevice]) => (
      registeredId !== deviceId
        && cloudDeviceAliasesIntersect(registeredDevice.device_aliases, device.device_aliases)
    ));
    if (targetEntry) {
      const [targetDeviceId, targetDevice] = targetEntry;
      const currentTargetDevice = devicesById.get(targetDeviceId) || targetDevice;
      devicesById.set(targetDeviceId, mergeCloudConnectedDevice(currentTargetDevice, {
        ...device,
        device_id: targetDeviceId,
        display_name: currentTargetDevice.display_name,
        registered: true,
        web_only: false,
      }));
    }
    devicesById.delete(deviceId);
  });
}

function cloudDeviceRowsFromMap(devicesById, limit) {
  foldCloudWebOnlyDeviceRows(devicesById);
  pruneCloudRowsToRegisteredInventory(devicesById);
  return Array.from(devicesById.values()).slice(0, limit);
}

function cloudDeviceCandidatesFromRuntimeStatus(status) {
  const liveRuntime = status?.live_runtime_status || {};
  const clientConnection = liveRuntime?.client_connection || {};
  const machineSource = liveRuntime?.machines?.items
    || liveRuntime?.machines?.devices
    || liveRuntime?.machines
    || [];
  return [
    ...cloudDeviceCandidatesFromAccountSnapshot(cloudDeviceLiveStateFromRuntimeStatus(status)),
    ...safeCloudMcpArray(liveRuntime?.devices),
    ...safeCloudMcpArray(machineSource),
    ...safeCloudMcpArray(
      clientConnection?.active_desktop_devices,
    ),
  ];
}

function cloudConnectedDevicesFromRuntimeStatus(status) {
  const candidates = cloudDeviceCandidatesFromRuntimeStatus(status);
  const byId = new Map();
  candidates.forEach((candidate, index) => {
    const device = normalizeCloudConnectedDevice(candidate, index);
    if (!device) {
      return;
    }
    upsertCloudConnectedDevice(byId, device);
  });
  return cloudDeviceRowsFromMap(byId, 12);
}

function cloudKnownDevicesFromRuntimeStatus(status) {
  const candidates = cloudDeviceCandidatesFromRuntimeStatus(status);
  const byId = new Map();
  candidates.forEach((candidate, index) => {
    const device = normalizeCloudConnectedDevice(candidate, index, { includeOffline: true });
    if (!device) {
      return;
    }
    upsertCloudConnectedDevice(byId, device);
  });
  return cloudDeviceRowsFromMap(byId, 48);
}

function appendCloudDeviceCandidates(output, value, options = {}) {
  if (!value) {
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => appendCloudDeviceCandidates(output, item, options));
    return;
  }
  if (typeof value !== "object") {
    return;
  }
  if (Array.isArray(value.items)) {
    appendCloudDeviceCandidates(output, value.items, options);
    return;
  }
  if (Array.isArray(value.devices)) {
    appendCloudDeviceCandidates(output, value.devices, options);
    return;
  }
  const looksLikeDevice = Boolean(
    value.device_id || value.machine_id || value.native_connected !== undefined || value.web_connected !== undefined,
  );
  if (looksLikeDevice) {
    output.push(options.registered ? { ...value, registered: true } : value);
    return;
  }
  Object.values(value).forEach((item) => appendCloudDeviceCandidates(output, item, options));
}

function cloudDeviceCandidatesFromAccountSnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== "object") {
    return [];
  }
  const root = snapshot?.data && typeof snapshot.data === "object" ? snapshot.data : snapshot;
  const accountSnapshot = root.account_device_live_state_snapshot || root.device_live_state_snapshot || null;
  const snapshotRoot = accountSnapshot && typeof accountSnapshot === "object"
    ? accountSnapshot
    : root;
  const clientConnection = snapshotRoot.client_connection || {};
  const connectionOverlay = cloudDeviceConnectionOverlayFromSnapshot(root, snapshotRoot);
  const output = [];
  appendCloudDeviceCandidates(output, root.registered_devices, { registered: true });
  appendCloudDeviceCandidates(output, root.device_registry, { registered: true });
  appendCloudDeviceCandidates(output, snapshotRoot.registered_devices, { registered: true });
  appendCloudDeviceCandidates(output, snapshotRoot.device_registry, { registered: true });
  appendCloudDeviceCandidates(output, snapshotRoot.device);
  appendCloudDeviceCandidates(output, snapshotRoot.devices);
  appendCloudDeviceCandidates(output, snapshotRoot.device_map);
  appendCloudDeviceCandidates(output, snapshotRoot.items);
  appendCloudDeviceCandidates(output, snapshotRoot.server_roster);
  appendCloudDeviceCandidates(output, clientConnection.active_desktop_devices);
  appendCloudDeviceCandidates(output, clientConnection.active_web_devices);
  return applyCloudDeviceConnectionOverlay(output, connectionOverlay);
}



function cloudDeviceLiveStateFromRuntimeStatus(status) {
  const liveRuntime = status?.live_runtime_status || {};
  const clientConnection = liveRuntime?.client_connection || {};
  const snapshot = [
    status?.account_device_live_state_snapshot,
    status?.device_live_state_snapshot,
    liveRuntime?.account_device_live_state_snapshot,
    liveRuntime?.device_live_state_snapshot,
    clientConnection?.account_device_live_state_snapshot,
  ].find((value) => value && typeof value === "object") || null;
  const serverRoster = [
    status?.server_roster,
    status?.account_device_server_roster,
    liveRuntime?.server_roster,
    liveRuntime?.account_device_server_roster,
    clientConnection?.server_roster,
  ].find((value) => value && (typeof value === "object" || Array.isArray(value))) || null;

  if (!snapshot && !serverRoster) {
    return null;
  }

  return {
    ...(snapshot && !Array.isArray(snapshot) ? snapshot : {}),
    ...(snapshot ? {
      account_device_live_state_snapshot: snapshot,
    } : {}),
    ...(serverRoster ? {
      server_roster: serverRoster,
    } : {}),
  };
}

function cloudAccountDeviceLiveStateSnapshotValueLooksLive(value) {
  return Boolean(
    value
      && typeof value === "object"
      && !Array.isArray(value)
      && (
        value.devices || value.device_map || value.registered_devices || value.device_registry || value.client_connection
      ),
  );
}

function cloudAccountDeviceLiveStateSnapshotFromValue(value, depth = 0) {
  if (!value || typeof value !== "object" || Array.isArray(value) || depth > 5) {
    return null;
  }
  if (cloudAccountDeviceLiveStateSnapshotValueLooksLive(value)) {
    return value;
  }
  for (const key of [
    "initial_account_live_state",
    "account_live_state",
    "account_device_live_state_snapshot",
    "device_live_state_snapshot",
    "data",
    "payload",
    "event",
  ]) {
    const snapshot = cloudAccountDeviceLiveStateSnapshotFromValue(value[key], depth + 1);
    if (snapshot) {
      return snapshot;
    }
  }
  return null;
}




function cloudStorageUsageFromRuntimeStatus(status) {
  const liveRuntime = status?.live_runtime_status || {};
  const storageUsage = status?.storage_usage || liveRuntime?.storage_usage || null;
  return storageUsage && typeof storageUsage === "object" ? storageUsage : null;
}

function cloudAccountUsageSnapshotFromEventPayload(payload) {
  const envelope = payload && typeof payload === "object" ? payload : {};
  const liveRuntime = envelope.live_runtime_status || {};
  const data = envelope.data && typeof envelope.data === "object" ? envelope.data : null;
  const payloadObject = envelope.payload && typeof envelope.payload === "object" ? envelope.payload : null;
  const direct = envelope.account_usage_snapshot
    || envelope.runtime_account_usage
    || envelope.account_usage
    || envelope.billing_status
    || envelope.account_status
    || liveRuntime.account_usage_snapshot
    || liveRuntime.runtime_account_usage
    || liveRuntime.account_usage
    || payloadObject?.account_usage_snapshot
    || payloadObject?.runtime_account_usage
    || payloadObject?.account_usage
    || payloadObject?.billing_status
    || data?.account_usage_snapshot
    || data?.runtime_account_usage
    || data?.account_usage
    || data?.billing_status
    || (data && Object.keys(data).length ? data : null)
    || (String(envelope.contract || "") === "diffforge.account_usage.v1"
      ? envelope.payload
      : null)
    || (String(envelope.kind || envelope.event_kind || "") === "account_usage_snapshot"
      ? envelope.payload
      : null)
    || envelope;
  const snapshot = direct && typeof direct === "object" ? direct : {};
  const nestedData = snapshot.data && typeof snapshot.data === "object" ? snapshot.data : {};
  const nestedPayload = snapshot.payload && typeof snapshot.payload === "object" ? snapshot.payload : {};
  const billingStatus = snapshot.billingStatus
    || snapshot.billing_status
    || snapshot.accountStatus
    || snapshot.account_status
    || nestedData.billingStatus
    || nestedData.billing_status
    || nestedData.accountStatus
    || nestedData.account_status
    || nestedPayload.billingStatus
    || nestedPayload.billing_status
    || nestedPayload.accountStatus
    || nestedPayload.account_status
    || {};
  const credits = snapshot.credits
    || snapshot.wallet
    || billingStatus.credits
    || billingStatus.wallet
    || nestedData.credits
    || nestedData.wallet
    || nestedPayload.credits
    || nestedPayload.wallet
    || null;
  const storageUsage = snapshot.storageUsage
    || snapshot.storage_usage
    || nestedData.storageUsage
    || nestedData.storage_usage
    || nestedPayload.storageUsage
    || nestedPayload.storage_usage
    || null;
  return {
    snapshot,
    credits: credits && typeof credits === "object" ? credits : null,
    storage_usage: storageUsage && typeof storageUsage === "object" ? storageUsage : null,
  };
}

function billingStatusFromAccountUsagePayload(payload, previousBillingStatus = null) {
  const { snapshot, credits } = cloudAccountUsageSnapshotFromEventPayload(payload);
  const sourceCredits = credits || snapshot?.credits;
  if (!liveCreditHasMeaningfulSnapshot(sourceCredits)) {
    return null;
  }
  const preferIncomingCredits = liveCreditSnapshotIsAuthoritative(sourceCredits, snapshot);
  if (!preferIncomingCredits && sourceCredits?.known === false && sourceCredits?.live !== true) {
    return null;
  }
  const normalizedCredits = normalizeLiveCreditWallet(sourceCredits, billingStatusCredits(previousBillingStatus), {
    preferIncomingTotals: preferIncomingCredits,
  });
  if (!normalizedCredits) {
    return null;
  }
  return mergeBillingStatusSnapshot(previousBillingStatus, {
    credits: normalizedCredits,
    plan_name: normalizedCredits.planName
      || normalizedCredits.plan_name
      || snapshot?.planName
      || snapshot?.plan_name
      || billingStatusPlanName(previousBillingStatus),
    plan_status: snapshot?.planStatus
      || snapshot?.plan_status
      || billingStatusPlanStatus(previousBillingStatus)
      || "paid",
  }, {
    preferIncomingCredits,
  });
}


