          error: failed[0] || "",
          meta: `${Math.min(index + 1, total)} of ${total} graphs`,
          percent: Math.round(((index + 1) / total) * 100),
          state: failed.length ? "error" : "hydrating",
          title: failed.length ? "Architecture hydration needs attention" : "Hydrating architectures",
          visible: true,
