  const refreshBillingStatus = useCallback(async ({ quiet = false } = {}) => {
    const requestSequence = billingRequestSequenceRef.current + 1;
    billingRequestSequenceRef.current = requestSequence;
    const expectedAccountKey = currentBillingAccountKeyRef.current;
    const requestIsCurrent = () => (
      requestSequence === billingRequestSequenceRef.current
      && expectedAccountKey === currentBillingAccountKeyRef.current
      && authStateRef.current === "authenticated"
    );
    // authState via ref keeps this callback's identity stable — it sits in the
    // auth startup effect's dependency chain (see authStateRef above).
    if (authStateRef.current !== "authenticated" || !expectedAccountKey) {
      setBillingStatus(null);
      setBillingStatusState("idle");
      setBillingStatusError("");
      return null;
    }

    if (!quiet) {
      setBillingStatusState("loading");
    } else {
      setBillingStatusState((current) => (current === "idle" ? "loading" : current));
    }

    try {
      const cloudRuntimeStatus = await invoke("cloud_mcp_get_status").catch(() => null);
      if (!requestIsCurrent()) {
        return null;
      }
      const cachedUsage = cloudAccountUsageSnapshotFromEventPayload(cloudRuntimeStatus);
      const cachedUsageMatchesAccount = accountUsageMatchesCurrentAccount(
        cloudRuntimeStatus,
        cachedUsage.snapshot,
        currentBillingAccountAliasesRef.current,
      );
      const websocketConnected = Boolean(
        cloudRuntimeStatus?.global_ws_connected ?? cloudRuntimeStatus?.connected,
      );
      if (websocketConnected && cachedUsageMatchesAccount) {
        const liveBillingStatus = billingStatusFromAccountUsagePayload(
          cloudRuntimeStatus,
          billingStatusRef.current,
        );
        if (liveBillingStatus) {
          if (!requestIsCurrent()) {
            return null;
          }
          const appliedSnapshot = await authStore.applyBillingStatus(liveBillingStatus, {
            expectedAccountKey,
          });
          if (
            !requestIsCurrent()
            || billingAccountKey(appliedSnapshot?.accountKey) !== expectedAccountKey
            || !billingStatusHasMeaningfulData(appliedSnapshot?.billingStatus)
          ) {
            return null;
          }
          const appliedBillingStatus = appliedSnapshot.billingStatus;
          billingStatusRef.current = appliedBillingStatus;
          setBillingStatus(appliedBillingStatus);
          setBillingStatusState("ready");
          setBillingStatusError("");
          return appliedBillingStatus;
        }
      }
      const nextBillingStatus = await invoke("cloud_mcp_get_billing_status");
      if (!requestIsCurrent()) {
        return null;
      }
      const mergedBillingStatus = mergeBillingStatusSnapshot(
        billingStatusRef.current,
        nextBillingStatus,
      );
      if (mergedBillingStatus) {
        if (!requestIsCurrent()) {
          return null;
        }
        const appliedSnapshot = await authStore.applyBillingStatus(mergedBillingStatus, {
          expectedAccountKey,
        });
        if (
          !requestIsCurrent()
          || billingAccountKey(appliedSnapshot?.accountKey) !== expectedAccountKey
          || !billingStatusHasMeaningfulData(appliedSnapshot?.billingStatus)
        ) {
          return null;
        }
        const appliedBillingStatus = appliedSnapshot.billingStatus;
        billingStatusRef.current = appliedBillingStatus;
        setBillingStatus(appliedBillingStatus);
        setBillingStatusState("ready");
        setBillingStatusError("");
        return appliedBillingStatus;
      }
      if (!requestIsCurrent()) {
        return null;
      }
      setBillingStatusState("ready");
      setBillingStatusError("");
      return null;
    } catch (error) {
      if (!requestIsCurrent()) {
        return null;
      }
      const message = getErrorMessage(error, "Unable to load credit status.");
      setBillingStatusState((current) => (
        billingStatusRef.current ? "ready" : current === "ready" ? "ready" : "error"
      ));
      setBillingStatusError(message);
      return null;
    }
  }, []);

  // ----- low-credits startup top-up -----
  // idle | shown | skipped | dismissed — decided once per sign-in from the
  // first ready billing snapshot, so the overlay only ever appears at startup.
  const [lowCreditsUpsellState, setLowCreditsUpsellState] = useState("idle");
  // idle | opening | waiting — waiting means checkout was handed to the browser.
  const [lowCreditsCheckoutState, setLowCreditsCheckoutState] = useState("idle");
  const [lowCreditsCheckoutError, setLowCreditsCheckoutError] = useState("");
  // Balance when the overlay first showed; a >= pack-size jump above it while
  // a checkout is pending is the purchase landing.
  const lowCreditsBaselineRemainingRef = useRef(null);
  const cloudCreditsRefreshSeqRef = useRef(0);

  const handleLowCreditsDismiss = useCallback(() => {
    cloudCreditsRefreshSeqRef.current += 1;
    setLowCreditsUpsellState("dismissed");
    setLowCreditsCheckoutState("idle");
    setLowCreditsCheckoutError("");
  }, []);

  const handleLowCreditsTopup = useCallback(async (packs) => {
    setLowCreditsCheckoutState("opening");
    setLowCreditsCheckoutError("");
    try {
      const checkout = await invoke("desktop_billing_start_topup_checkout", { packs });
      const checkoutUrl = String(checkout?.url || "");
      if (!/^https:\/\//i.test(checkoutUrl)) {
        throw new Error("Checkout link unavailable. Try again.");
      }
      await openUrl(checkoutUrl);
      setLowCreditsCheckoutState("waiting");
    } catch (error) {
      setLowCreditsCheckoutState("idle");
      setLowCreditsCheckoutError(getErrorMessage(error, "Unable to start checkout. Try again."));
    }
  }, []);

  // Stripe's webhook can trail the browser redirect by a few seconds. Ask
  // cloud to drop its cached wallet and re-read the billing DB a few times;
  // the refreshed snapshot also re-broadcasts to every connected device.
  const requestCloudCreditsRefresh = useCallback(async () => {
    const seq = cloudCreditsRefreshSeqRef.current + 1;
    cloudCreditsRefreshSeqRef.current = seq;
    const delaysMs = [0, 3500, 9000, 20000];
    for (const delayMs of delaysMs) {
      if (delayMs) {
        await new Promise((resolve) => window.setTimeout(resolve, delayMs));
      }
      if (cloudCreditsRefreshSeqRef.current !== seq) {
        return;
      }
      try {
        await invoke("cloud_mcp_refresh_billing_status", { reason: "credits_topup_return" });
      } catch {
        // fall through to the regular status pipeline
      }
      const refreshed = await refreshBillingStatus({ quiet: true }).catch(() => null);
      const refreshedCredits = billingStatusCredits(refreshed);
      const remaining = Number(
        refreshedCredits?.termRemainingCredits ?? refreshedCredits?.term_remaining_credits,
      );
      const baseline = Number(lowCreditsBaselineRemainingRef.current);
      if (
        Number.isFinite(remaining)
        && Number.isFinite(baseline)
        && remaining - baseline >= LOW_CREDITS_TOPUP_SUCCESS_MIN_CREDITS
      ) {
        return;
      }
    }
  }, [refreshBillingStatus]);

  // Handles <scheme>://billing/topup?status=... deep links from the web
